Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h> 
#define lld long long 
using namespace std;
const lld mod1 = 998244353;
const lld mod2 = 1e9 + 7;
lld ans;
lld n;
lld cnt1;
vector < lld > val[7];
lld sum[7];
void dfs1 (lld k1, lld k2) {
	if (k1 == 7) return;
	val[k1].push_back((cnt1 - k2 + mod1) % mod1);
	sum[k1] += (cnt1 - k2 + mod1) % mod1;
	++ cnt1;
	for (lld i = 0; i <= 9; ++ i)
		dfs1 (k1 + 1, k2 * 10 + i);
}
inline bool check(lld x) { return x * 1000000 + 999999 <= n && x * 10000000 > n; }
lld cnt2;
lld poww[7] = { 1, 10, 100, 1000, 10000, 100000, 1000000 };
void dfs2(lld k1, lld k2) {
	if (k2 > n) return;
	if (check(k2)) {
		for (lld i = 0; i <= 6; ++ i) {
			lld offset = ((cnt2 + 1 - (k2 * poww[i])) % mod1 + mod1) % mod1;
			lld pos = lower_bound(val[i].begin(), val[i].end(), mod1 - offset) - val[i].begin();
			ans = (ans + (sum[i] + offset * val[i].size() - mod1 * (val[i].size() - pos))) % mod2;
		}
		cnt2 += cnt1;
	} else {
		++ cnt2;
		ans = (ans + ((cnt2 - k2) % mod1 + mod1) % mod1) % mod2;
		for (lld i = (!k1); i <= 9; ++ i)
			dfs2(k1 + 1, k2 * 10 + i);
	}
}
int main() {
	scanf("%lld", & n);
	dfs1 (0, 0);
	for (lld i = 0; i <= 6; ++ i) sort(val[i].begin(), val[i].end());
	cnt2 = -1;
	dfs2 (0, 0);
	printf("%lld\n", ans);
}

</original_code>
